import{z as p,x as d,o as i,c as B,q as s,j as n,D as e,d as r,s as E,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"二分图匹配","description":"","frontmatter":{"title":"二分图匹配","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bipartite-match.md","filePath":"cs/bipartite-match.md","lastUpdated":1791063341000}'),A={name:"cs/bipartite-match.md"};function m(h,a,D,u,f,c){const l=d("Mermaid");return i(),B("div",null,[a[2]||(a[2]=s('<h1 id="二分图匹配" tabindex="-1">二分图匹配 <a class="header-anchor" href="#二分图匹配" aria-label="Permalink to &quot;二分图匹配&quot;">​</a></h1><div class="epigraph"><p>最大匹配等于最小点覆盖；单位容量网络上最大流给出最大匹配。</p><footer>—— 据 König, 1931；Hopcroft and Karp, An $n^{5/2}$ Algorithm for Maximum Matchings in Bipartite Graphs, 1973；CLRS 第 26.3 节整理</footer></div><p>上一课<a href="/cs/dinic">Edmonds–Karp 与 Dinic</a>把最大流变成多项式增广。本课不重写分层。缺口是组合对象<strong>匹配</strong>：边子集、任意点至多关联一条。二分图 \\(G=(L\\cup R,E)\\) 上，最大基数匹配等于以 \\(s\\to L\\to R\\to t\\)、边容量 \\(1\\) 的最大流。König：最大匹配 = 最小点覆盖。后课离开图，进入串。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>贪心随便取边得不到最大。交错路：从自由点出发，非匹配/匹配交替，增广路定理（Berge）说匹配最大当且仅当无增广路——与残量 \\(s\\)–\\(t\\) 路同一图像。构造网络：超源连 \\(L\\) 容量 \\(1\\)，\\(R\\) 连超汇容量 \\(1\\)，原边 \\(L\\to R\\) 容量 \\(1\\)。整流对应匹配。缺口是这层翻译，不是再证最大流最小割。</p><p>Hall 条件：对任意 \\(S\\subseteq L\\)，\\(|N(S)|\\ge|S|\\) 当且仅当存在饱和 \\(L\\) 的匹配。本课点名，不把婚配定理证完。</p><p><span class="marginnote">Hall 条件用数字体会最直接：左边 3 个学生都只想上 {乒乓球, 围棋} 这 2 门课，则 \\(|N(S)|=2 \\lt |S|=3\\)，条件不满足，必然有人选不上课。它把「能不能全配上」翻译成了对每组候选的一个不等式。</span></p><h3 id="一般图不是本课" tabindex="-1">一般图不是本课 <a class="header-anchor" href="#一般图不是本课" aria-label="Permalink to &quot;一般图不是本课&quot;">​</a></h3><p>带花的 Edmonds 算法处理非二分；本课只二分。不要把「每次找一条交错路」在奇环上当多项式显然。</p><p><span class="marginnote">König 定理是二分图上最大匹配/最小覆盖的对偶。Hopcroft–Karp 1973 一次找一组最短增广，时间 \\(O(E\\sqrt V)\\)，与单位容量 Dinic 同类。CLRS 26.3 用流做匹配。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建单位网络，跑上一课的最大流。匹配边即 \\(L\\to R\\) 上流量为 \\(1\\) 的边。最小点覆盖：最大流后残量里 \\(s\\) 可达的 \\(L\\) 与不可达的 \\(R\\) 等标准构造，本课认「覆盖数等于匹配数」，不手画全部情形。</p>',12)),(i(),n(o,null,{default:e(()=>[E(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20BG%5B%22%E4%BA%8C%E5%88%86%E5%9B%BE%22%5D%20--%3E%20NET%5B%22s-L-R-t%20%E5%8D%95%E4%BD%8D%E5%AE%B9%E9%87%8F%22%5D%0A%20%20NET%20--%3E%20FLOW%5B%22%E6%9C%80%E5%A4%A7%E6%B5%81%22%5D%0A%20%20FLOW%20--%3E%20M%5B%22%E6%9C%80%E5%A4%A7%E5%8C%B9%E9%85%8D%22%5D%0A%20%20M%20--%3E%20K%5B%22%E6%9C%80%E5%B0%8F%E7%82%B9%E8%A6%86%E7%9B%96%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"匈牙利算法是交错路的直接实现，与单位流增广等价。本课以流为接口，避免两套术语。",-1)),a[4]||(a[4]=t("p",null,[t("span",{class:"marginnote"},"初学者容易以为「贪心把能配的边都配上」就是最大匹配；实际上一步选错可能堵死后面所有的配对。交错路正是「反悔」机制：沿增广路把匹配边与非匹配边互换，旧配对没破坏，总数却多了 1。")],-1)),a[5]||(a[5]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=t("p",null,"整数容量保证整流。多源任务分配：左边人、右边岗位，即本课。权匹配（KM / 费用流）不在本课。也不要把 MST 的边集当匹配：度数可以大于 \\(1\\)。",-1)),a[7]||(a[7]=t("p",null,[t("a",{href:"/cs/dfs-edge-types"},"DFS 边分类"),r("的交错路是这条图上的路径，不是 DFS 森林的四类边。")],-1)),a[8]||(a[8]=t("p",null,"增广路的细节值得单独画出来：它回答「找到一条路之后，匹配到底怎么 +1」。",-1)),(i(),n(o,null,{default:e(()=>[E(l,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20FL%5B%22%E8%87%AA%E7%94%B1%E5%B7%A6%E7%82%B9%22%5D%20--%3E%7C%22%E9%9D%9E%E5%8C%B9%E9%85%8D%E8%BE%B9%22%7C%20R1%5B%22%E5%B7%B2%E9%85%8D%E5%AF%B9%E7%9A%84%E5%8F%B3%E7%82%B9%22%5D%0A%20%20R1%20--%3E%7C%22%E5%8C%B9%E9%85%8D%E8%BE%B9%22%7C%20L2%5B%22%E5%AE%83%E5%8E%9F%E6%9D%A5%E7%9A%84%E5%B7%A6%E6%90%AD%E6%A1%A3%22%5D%0A%20%20L2%20--%3E%7C%22%E9%9D%9E%E5%8C%B9%E9%85%8D%E8%BE%B9%22%7C%20R2%5B%22%E8%87%AA%E7%94%B1%E5%8F%B3%E7%82%B9%22%5D%0A%20%20R2%20--%3E%20GAIN%5B%22%E6%95%B4%E6%9D%A1%E7%BF%BB%E8%BD%AC%EF%BC%9A%E5%8C%B9%E9%85%8D%E6%95%B0%20%2B1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=s('<p><span class="marginnote">「增广路」就是一条起点终点都是自由点的交错路径，作用是腾位置：把路上匹配/非匹配身份对调，原来的配对一个不丢，总匹配数恰好多 1。可以想象成换座位——新同学进来，先坐空位，被挤走的人再坐另一个空位，一圈下来人人有座。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做一般图匹配、不做稳定婚配的 Gale–Shapley。后课默认：二分最大匹配 = 单位最大流，基数多项式可算。串匹配是另一类对象：文本与模式，不是点对边。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二分最大匹配 ↔ 单位容量最大流。</li><li>最大匹配 = 最小点覆盖（König）。</li><li>一般图带花，不在本课。</li><li>出处：König；Hopcroft and Karp, 1973；CLRS 第 26.3 节。</li></ul>',5))])}const g=p(A,[["render",m]]);export{b as __pageData,g as default};
